import {rng} from './engine.mjs';
const dominates=(a,b)=>a.oil>=b.oil&&a.water<=b.water&&(a.oil>b.oil||a.water<b.water);
function fronts(pop){const remain=new Set(pop),layers=[];while(remain.size){const front=[...remain].filter(b=>![...remain].some(a=>a!==b&&dominates(a,b)));for(const p of front)remain.delete(p);layers.push(front);}return layers;}
function crowd(front){for(const p of front)p.crowding=0;for(const k of ['oil','water']){const s=[...front].sort((a,b)=>a[k]-b[k]),span=s.at(-1)?.[k]-s[0]?.[k]||1;if(!s.length)continue;s[0].crowding=Infinity;s.at(-1).crowding=Infinity;for(let i=1;i<s.length-1;i++)s[i].crowding+=(s[i+1][k]-s[i-1][k])/span;}return front;}
export function nsga({handling,cap,wc1,wc2,seed=42,generations=40,size=50}){if(![handling,cap,wc1,wc2].every(Number.isFinite)||handling<0||cap<0)throw Error('处理能力和上限必须为有限非负数');if(wc1<0||wc1>=1||wc2<0||wc2>=1)throw Error('含水率需在0–100%且小于100%');const random=rng(seed),make=(q1,q2)=>{q1=Math.max(0,Math.min(cap,q1));q2=Math.max(0,Math.min(cap,q2));const scale=q1+q2>handling?handling/(q1+q2):1;q1*=scale;q2*=scale;return {q1,q2,oil:q1*(1-wc1)+q2*(1-wc2),water:q1*wc1+q2*wc2};};let pop=Array.from({length:size},()=>make(random()*cap,random()*cap));for(let g=0;g<generations;g++){const layers=fronts(pop);layers.forEach((f,rank)=>crowd(f).forEach(p=>p.rank=rank));const pick=()=>{const a=pop[Math.floor(random()*pop.length)],b=pop[Math.floor(random()*pop.length)];return a.rank<b.rank||a.rank===b.rank&&a.crowding>b.crowding?a:b;};const children=Array.from({length:size},()=>{const a=pick(),b=pick(),t=random();return make(t*a.q1+(1-t)*b.q1+(random()-.5)*cap*.15,t*a.q2+(1-t)*b.q2+(random()-.5)*cap*.15);});pop=[];for(const f of fronts([...layers.flat(),...children])){crowd(f);if(pop.length+f.length<=size)pop.push(...f);else{pop.push(...f.sort((a,b)=>b.crowding-a.crowding).slice(0,size-pop.length));break;}}}const front=fronts(pop)[0].sort((a,b)=>a.oil-b.oil),unique=[...new Map(front.map(p=>[p.q1.toFixed(2)+'/'+p.q2.toFixed(2),p])).values()];return unique.filter((_,i)=>i%Math.max(1,Math.floor(unique.length/12))===0).slice(0,15).map(({q1,q2,oil,water})=>({q1,q2,oil,water}));}
